<section class="panel form-panel"><div class="panel-head"><div><span class="eyebrow">SQUAD MANAGEMENT</span><h2><?= $player?'Update player details':'Register a player' ?></h2></div><a class="text-link" href="index.php?route=players">← Back to players</a></div>
<form method="post" action="index.php?route=players/save" class="form-grid"><?= csrf_field() ?><?php if($player): ?><input type="hidden" name="id" value="<?= e($player['id']) ?>"><?php endif; ?>
<label class="wide">Full name<input name="full_name" required value="<?= e($player['full_name']??'') ?>"></label><label>Position<select name="position" required><?php foreach(['Goalkeeper','Defender','Midfielder','Forward'] as $v): ?><option <?= (($player['position']??'')===$v)?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label><label>Jersey number<input type="number" min="1" name="jersey_no" required value="<?= e($player['jersey_no']??'') ?>"></label><label>Date of birth<input type="date" name="dob" value="<?= e($player['dob']??'') ?>"></label><label>Phone number<input name="phone" value="<?= e($player['phone']??'') ?>"></label><label>Status<select name="status"><?php foreach(['active','injured','inactive'] as $v): ?><option value="<?= e($v) ?>" <?= (($player['status']??'active')===$v)?'selected':'' ?>><?= e(ucfirst($v)) ?></option><?php endforeach; ?></select></label><div class="wide"><button class="btn">Save player</button></div></form></section>